"""Measured Native body footprint relative to a reviewed parking polygon.

The polygon must be derived from inspected map geometry. The caller retains its
map/source hash and original frame; this function does not create an intersection.
"""
from __future__ import annotations

import math


def _point_inside(point, polygon):
    x, y = point
    inside = False
    for i, (x1, y1) in enumerate(polygon):
        x2, y2 = polygon[(i + 1) % len(polygon)]
        cross = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1)
        if abs(cross) < 1e-9 and min(x1, x2) - 1e-9 <= x <= max(x1, x2) + 1e-9 and min(y1, y2) - 1e-9 <= y <= max(y1, y2) + 1e-9:
            return True
        if (y1 > y) != (y2 > y):
            if x < x1 + (x2 - x1) * (y - y1) / (y2 - y1):
                inside = not inside
    return inside


def classify_footprint(body_corners_xy_m, reviewed_parking_polygon_xy_m,
                       reviewed_intersection_polygon_xy_m):
    """Return full-footprint containment and physical intersection overlap.

    All inputs are actual Native world XY coordinates. A body corner inside the
    intersection polygon is a conservative overlap witness; false means no
    corner witness, not proof the polygons are disjoint.
    """
    body = body_corners_xy_m
    parking = reviewed_parking_polygon_xy_m
    intersection = reviewed_intersection_polygon_xy_m
    if len(body) != 4 or len(parking) < 3 or len(intersection) < 3:
        raise ValueError("four body corners and reviewed polygons required")
    for point in (*body, *parking, *intersection):
        if len(point) != 2 or not all(type(v) in (int, float) and math.isfinite(v) for v in point):
            raise ValueError("invalid original world XY")
    return {"footprint_inside_reviewed_parking_polygon": all(_point_inside(p, parking) for p in body),
            "body_corner_inside_intersection_count": sum(_point_inside(p, intersection) for p in body),
            "intersection_overlap_method": "body_corner_witness_only"}

"""Four original CARLA camera archives for a parked-headlamp Native attempt.

Sensors are caller-owned. This adapter owns the listeners and lossless archives;
actual beam emission and physical aim require later original-image review.
"""
from __future__ import annotations

import hashlib
import io
from pathlib import Path
from queue import Empty, Queue
import subprocess
import zipfile

from PIL import Image

VIEWS = ("overview", "approach", "reference_corner", "driver_reference")
PROFILE_DIMENSIONS = {
    "overview": (1920, 1080),
    "approach": (1280, 720),
    "reference_corner": (1280, 720),
    "driver_reference": (1280, 720),
}


def encode_original_videos(output: Path, frame_rows: list[dict], *, rate_hz: int = 20) -> dict:
    """Encode the retained original PNG frames without altering their archives."""
    output = Path(output)
    if rate_hz != 20 or not frame_rows or any(
            row['video_frame'] != index or type(row['carla_frame']) is not int
            for index, row in enumerate(frame_rows)):
        raise ValueError('original 20 Hz video frame map invalid')
    references = {}
    for view in VIEWS:
        archive_path = output / (view + '.zip')
        movie = output / (view + '.mkv')
        if movie.exists():
            raise ValueError('original movie already exists: ' + movie.name)
        with zipfile.ZipFile(archive_path) as archive:
            expected = [str(row['carla_frame']) + '.png' for row in frame_rows]
            if archive.namelist() != expected:
                raise ValueError('original camera archive/frame map differs: ' + view)
            command = ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y',
                       '-framerate', str(rate_hz), '-f', 'image2pipe', '-vcodec', 'png',
                       '-i', 'pipe:0', '-an', '-c:v', 'ffv1', '-level', '3', str(movie)]
            process = subprocess.Popen(command, stdin=subprocess.PIPE,
                                       stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
            try:
                for name in expected:
                    process.stdin.write(archive.read(name))
                process.stdin.close()
                error = process.stderr.read().decode('utf-8', errors='replace')
                code = process.wait()
            except Exception:
                process.kill()
                process.wait()
                raise
            if code != 0 or not movie.is_file() or movie.stat().st_size == 0:
                raise ValueError('original camera encode failed: ' + view + ': ' + error[-500:])
        references[view] = {'path': movie.name,
                            'sha256': hashlib.sha256(movie.read_bytes()).hexdigest(),
                            'source_frame_count': len(frame_rows)}
    return references


class CameraRecorder:
    def __init__(self, sensors: dict, output: Path, *, timeout_seconds: float = 5.0,
                 dimensions: dict | None = None):
        if set(sensors) != set(VIEWS) or timeout_seconds <= 0:
            raise ValueError("four sensors and positive timeout required")
        dimensions = PROFILE_DIMENSIONS if dimensions is None else dimensions
        if set(dimensions) != set(VIEWS) or any(
                not isinstance(dimensions[view], (tuple, list)) or
                len(dimensions[view]) != 2 or
                any(type(size) is not int or size <= 0 for size in dimensions[view])
                for view in VIEWS):
            raise ValueError("four positive camera dimensions required")
        self.sensors = sensors
        self.output = Path(output)
        self.timeout_seconds = timeout_seconds
        self.dimensions = {view: tuple(dimensions[view]) for view in VIEWS}
        self.queues = {view: Queue() for view in VIEWS}
        self.listening = []
        self.archives = {}
        self.frames = 0
        self.closed = False

    def start(self):
        if self.listening or self.closed:
            raise ValueError("camera recorder already started or closed")
        self.output.mkdir(parents=True, exist_ok=True)
        if any((self.output / (view + ".zip")).exists() for view in VIEWS):
            raise ValueError("original camera archive already exists")
        try:
            for view in VIEWS:
                sensor = self.sensors[view]
                sensor.listen(lambda image, name=view: self.queues[name].put(image))
                self.listening.append(sensor)
            self.archives = {view: zipfile.ZipFile(self.output / (view + ".zip"), "w",
                             compression=zipfile.ZIP_STORED) for view in VIEWS}
        except Exception:
            self.close()
            raise

    @staticmethod
    def _png(image, expected_dimensions: tuple[int, int]) -> bytes:
        width, height = image.width, image.height
        if (type(width) is not int or type(height) is not int or
                width <= 0 or height <= 0):
            raise ValueError("original camera dimensions invalid")
        if (width, height) != expected_dimensions:
            raise ValueError("original camera dimensions differ from capture profile")
        raw = bytes(image.raw_data)
        if len(raw) != width * height * 4:
            raise ValueError("original camera BGRA byte count mismatch")
        rgb = Image.frombytes("RGBA", (width, height), raw, "raw", "BGRA").convert("RGB")
        stream = io.BytesIO()
        rgb.save(stream, format="PNG")
        return stream.getvalue()

    def __call__(self, frame: int) -> dict:
        if self.closed or len(self.archives) != 4 or type(frame) is not int:
            raise ValueError("camera recorder not started")
        encoded = {}
        for view in VIEWS:
            try:
                image = self.queues[view].get(timeout=self.timeout_seconds)
            except Empty as exc:
                raise ValueError("original camera callback missing: " + view) from exc
            if image.frame != frame:
                raise ValueError("original camera callback frame mismatch: " + view)
            encoded[view] = self._png(image, self.dimensions[view])
        for view in VIEWS:
            self.archives[view].writestr(f"{frame}.png", encoded[view])
        self.frames += 1
        return {view: frame for view in VIEWS}

    def finish(self, expected_frames: int) -> dict:
        if self.closed or self.frames != expected_frames:
            raise ValueError("original camera archive frame count incomplete")
        self.close()
        media = {}
        for view in VIEWS:
            path = self.output / (view + ".zip")
            with zipfile.ZipFile(path) as archive:
                if len(archive.namelist()) != expected_frames:
                    raise ValueError("original camera archive incomplete")
            media[view] = {"path": path.name,
                           "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                           "source_frame_count": expected_frames}
        return media

    def close(self):
        for sensor in self.listening:
            sensor.stop()
        self.listening.clear()
        for archive in self.archives.values():
            archive.close()
        self.closed = True

"""Independent saved-source integrity audit for the three parked-lamp cases.

This checks acquisition identity and sealed files. Video decoding and the
physical interpretation of emitted light remain separate review steps.
"""
from __future__ import annotations

import hashlib
import io
import json
from pathlib import Path
import zipfile

from PIL import Image

from lamp_probe import CASE_MODES
from saved_lamps import process_saved


ASSIGNMENT = "testing__C110454__NRS-484D-165-4__motor_vehicle_driver"
VIEWS = ("overview", "approach", "reference_corner", "driver_reference")
EXPECTED_FRAMES = 900  # 45 seconds at the pinned 20 Hz acquisition cadence.
PROFILE = {"overview": (1920, 1080), "approach": (1280, 720),
           "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _contained(root: Path, relative: str) -> Path:
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
        raise ValueError("media path must be attempt relative")
    target = (root / relative).resolve()
    if not target.is_relative_to(root.resolve()) or not target.is_file():
        raise ValueError("media path missing or escapes attempt")
    return target


def decode_original_cameras(paths: dict, camera_rows: list, *, dimensions=None) -> dict:
    """Decode every original frame at the exact Native frame identity."""
    sizes = PROFILE if dimensions is None else dimensions
    if set(paths) != set(VIEWS) or set(sizes) != set(VIEWS) or not camera_rows:
        raise ValueError("four original camera archives and frame rows required")
    frames = [row.get("frame") for row in camera_rows]
    if any(type(frame) is not int for frame in frames) or frames != list(range(frames[0], frames[0] + len(frames))):
        raise ValueError("original camera frame sequence invalid")
    counts = {}
    for view in VIEWS:
        with zipfile.ZipFile(paths[view]) as archive:
            names = archive.namelist()
            expected = [f"{frame}.png" for frame in frames]
            if len(names) != len(set(names)) or set(names) != set(expected):
                raise ValueError("original camera ZIP frame inventory differs: " + view)
            for frame, name in zip(frames, expected):
                row = camera_rows[frame - frames[0]]
                if row.get(view + "_source_frame") != frame:
                    raise ValueError("original camera frame map differs: " + view)
                with Image.open(io.BytesIO(archive.read(name))) as image:
                    if image.format != "PNG" or image.size != tuple(sizes[view]):
                        raise ValueError("original camera PNG profile differs: " + view)
                    image.load()
        counts[view] = len(frames)
    return counts


def audit(attempt: Path, manifest_path: Path, *, case_id: str,
          allow_diagnostic: bool = False) -> dict:
    """Audit one attempt's exact case, Native histories, and four media seals.

    The manifest is authored after capture and binds paths, hashes, source
    receipt, source map, and media. `allow_diagnostic` is only for CPU fixtures.
    """
    if case_id not in {ASSIGNMENT + "__" + mode for mode in CASE_MODES}:
        raise ValueError("unknown exact case ID")
    root = Path(attempt).resolve()
    manifest_file = Path(manifest_path)
    manifest = json.loads(manifest_file.read_text())
    if manifest.get("format") != "parked-headlamp-acquisition-v1" or manifest.get("case_id") != case_id:
        raise ValueError("saved acquisition case identity mismatch")
    if manifest.get("acquisition_kind") != "native" and not allow_diagnostic:
        raise ValueError("delivery requires Native acquisition")
    if manifest.get("physical_acceptance_claimed") is not False:
        raise ValueError("saved acquisition must not claim physical acceptance")
    receipt_record = manifest.get("native_receipt", {})
    receipt = _contained(root, receipt_record.get("path"))
    if _sha(receipt) != receipt_record.get("sha256"):
        raise ValueError("Native receipt hash changed")
    saved = process_saved(root, receipt, receipt_record["sha256"], case_id=case_id,
                          allow_diagnostic=allow_diagnostic)
    measured = saved["observation"]
    if measured["frame_count"] != EXPECTED_FRAMES:
        raise ValueError("saved acquisition is shorter than planned 45 seconds")
    mode = case_id.rsplit("__", 1)[1]
    if measured["parked_sample_count"] != EXPECTED_FRAMES:
        raise ValueError("parked footprint/brake/stationary observation incomplete")
    if mode == "unlit" and (measured["low_beam_readback_count"] or measured["high_beam_readback_count"]):
        raise ValueError("unlit readback differs from requested probe")
    if mode == "low_beam" and (measured["low_beam_readback_count"] != EXPECTED_FRAMES or measured["high_beam_readback_count"]):
        raise ValueError("low-beam readback differs from requested probe")
    if mode == "high_beam" and (measured["high_beam_readback_count"] != EXPECTED_FRAMES or measured["low_beam_readback_count"]):
        raise ValueError("high-beam readback differs from requested probe")
    media = manifest.get("media")
    if not isinstance(media, dict) or set(media) != set(VIEWS):
        raise ValueError("four exact original camera media sources required")
    media_hashes = {}
    media_paths = set()
    original_paths = {}
    for view in VIEWS:
        item = media[view]
        if not isinstance(item, dict) or item.get("source_frame_count") != EXPECTED_FRAMES:
            raise ValueError("camera source frame count missing")
        path = _contained(root, item.get("path"))
        if path in media_paths:
            raise ValueError("camera sources must be distinct")
        media_paths.add(path)
        digest = _sha(path)
        if path.stat().st_size == 0 or digest != item.get("sha256"):
            raise ValueError("original camera media hash changed or empty")
        media_hashes[view] = digest
        original_paths[view] = path
    decoded = None
    if not allow_diagnostic:
        camera_rows = [json.loads(line) for line in
                       (root / "camera-frame-map.jsonl").read_text().splitlines()]
        decoded = decode_original_cameras(original_paths, camera_rows)
        if any(count != EXPECTED_FRAMES for count in decoded.values()):
            raise ValueError("original camera decode frame count incomplete")
    return {"format": "parked-headlamp-delivery-integrity-v1", "case_id": case_id,
            "native_receipt_sha256": receipt_record["sha256"],
            "source_hashes": measured["source_hashes"], "media_hashes": media_hashes,
            "frame_count": EXPECTED_FRAMES, "saved_source_integrity_passed": True,
            "observation": measured,
            "full_video_decode_passed": decoded is not None,
            "decoded_frames_per_camera": decoded,
            "emission_and_aim_reviewed": False,
            "physical_acceptance_claimed": False}

